export function Role({
  roleName = "{{roleName}}",
  canPublish = {{canPublish}},
  canDelete = {{canDelete}},
  accent = "{{accent}}",
}) {
  const chip = { fontSize: 11, fontWeight: 700, padding: "5px 11px", borderRadius: 999, color: "#241430", background: accent };
  return (
    <div style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 12px" }}>Role: <strong>{roleName}</strong></p>
      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 12 }}>
        <span style={chip}>view</span>
        <span style={chip}>edit</span>
        {canPublish && <span style={chip}>publish</span>}
        {canDelete && <span style={chip}>delete</span>}
      </div>
      <p style={{ margin: 0, fontSize: 10, color: "#24143099" }}>A role is just a named bundle of permissions &mdash; assign the role, and every permission in it comes along.</p>
    </div>
  );
}
